import {scientists,fieldStudies} from './studio-data.js';
import {studioArt} from './studio-art.js';
export function createScientistPortal(root,api){
 let selected='mendel',step=0,correct=false,lastAnswer=-1;const sessions={},savedReflections={};
 root.innerHTML=`<div class="studio-section-head"><div><span class="studio-kicker">04 / CỔNG NHÀ KHOA HỌC</span><h2>Gặp một cách đặt câu hỏi.</h2><p>Đi theo bằng chứng cùng bốn câu chuyện khoa học. Thử dự đoán, nhận gợi ý và viết lại điều bạn vừa hiểu.</p></div><span class="studio-label">ĐỐI THOẠI GỢI MỞ</span></div><div class="scientist-picker" role="group" aria-label="Chọn nhà khoa học">${Object.entries(scientists).map(([id,s],i)=>`<button type="button" data-scientist="${id}"><span>0${i+1}</span><strong>${s.name}</strong><small>${s.topic}</small></button>`).join('')}</div><div class="scientist-layout"><aside class="scientist-portrait"><div id="scientist-art"></div><span class="studio-kicker" id="scientist-years"></span><h3 id="scientist-name"></h3><p id="scientist-context"></p><a id="scientist-source" target="_blank" rel="noopener noreferrer">Đọc nguồn lịch sử ↗</a></aside><div class="scientist-conversation"><span class="studio-label">TÁI HIỆN SƯ PHẠM · KỊCH BẢN CÓ NGUỒN</span><p class="studio-fineprint">Các câu hỏi do VNScape biên soạn, không phải lời trích nguyên văn hay trò chuyện AI trực tiếp. Phản hồi theo lựa chọn; phần tự viết được lưu nguyên văn.</p><div class="scientist-question"><span id="scientist-step" class="studio-kicker"></span><h3 id="scientist-question"></h3><div id="scientist-answers"></div><div id="scientist-feedback" class="scientist-feedback" role="status"></div><div class="studio-button-row"><button type="button" id="scientist-hint" class="studio-text-button">Gợi mở thêm ↗</button><button type="button" id="scientist-next" class="studio-button" hidden>Câu hỏi tiếp theo →</button></div></div><label for="scientist-reflection">Một điều tôi muốn giải thích bằng lời của mình</label><textarea id="scientist-reflection" rows="4" maxlength="1800" placeholder="Tôi đã dự đoán… Bằng chứng khiến tôi nghĩ lại… Câu hỏi tiếp theo của tôi là…"></textarea><div class="studio-button-row"><button type="button" id="scientist-save" class="studio-button secondary">Lưu cuộc gặp vào sổ tay</button><button type="button" id="scientist-replay" class="studio-text-button" hidden>Đặt lại câu hỏi ↺</button></div></div></div>`;
 function capture(){sessions[selected]={step,correct,lastAnswer,reflection:root.querySelector('#scientist-reflection').value}}
 function render(){const s=scientists[selected],q=s.questions[step],done=step>=s.questions.length;root.querySelector('#scientist-art').innerHTML=studioArt(s.artifact,`Minh họa ${s.topic}`);for(const [id,value] of [['scientist-years',s.years],['scientist-name',s.name],['scientist-context',s.context],['scientist-step',done?'MỘT CÂU HỎI MỚI ĐANG MỞ RA':`ĐỐI THOẠI ${step+1} / ${s.questions.length}`],['scientist-question',done?'Bạn muốn kiểm chứng điều gì tiếp theo?':q.question]])root.querySelector('#'+id).textContent=value;
 const source=root.querySelector('#scientist-source');source.href=s.source[1];source.textContent=s.source[0]+' ↗';root.querySelector('#scientist-answers').innerHTML=done?'':q.choices.map((text,i)=>`<button type="button" data-scientist-answer="${i}" class="${i===lastAnswer?'chosen':''} ${correct&&i===q.correct?'correct':''}" ${correct?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${text}</button>`).join('');
 root.querySelector('#scientist-feedback').textContent=done?'Bạn đã đi qua các gợi mở. Giờ hãy tách điều bạn biết, bằng chứng bạn có và điều vẫn cần kiểm chứng.':correct?q.explanation:lastAnswer>=0?q.hint:'';root.querySelector('#scientist-feedback').classList.toggle('is-correct',correct);root.querySelector('#scientist-next').hidden=!correct||done;root.querySelector('#scientist-next').textContent=step===s.questions.length-1?'Giữ lại một câu hỏi →':'Câu hỏi tiếp theo →';root.querySelector('#scientist-hint').hidden=correct||done;root.querySelector('#scientist-replay').hidden=!done;
 root.querySelectorAll('[data-scientist]').forEach(b=>{const active=b.dataset.scientist===selected;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));b.querySelector('span').textContent=api.isComplete('mentor-'+b.dataset.scientist)?'✓':String(Object.keys(scientists).indexOf(b.dataset.scientist)+1).padStart(2,'0')});
 }
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.scientist){capture();selected=b.dataset.scientist;const saved=sessions[selected];step=saved?.step||0;correct=saved?.correct||false;lastAnswer=saved?.lastAnswer??-1;root.querySelector('#scientist-reflection').value=saved?.reflection||'';render()}if(b.dataset.scientistAnswer!==undefined&&!correct&&scientists[selected].questions[step]){lastAnswer=Number(b.dataset.scientistAnswer);correct=lastAnswer===scientists[selected].questions[step].correct;render();if(correct)root.querySelector('#scientist-next').focus()}});
 root.querySelector('#scientist-next').addEventListener('click',()=>{if(!correct)return;step++;correct=false;lastAnswer=-1;if(step===scientists[selected].questions.length)api.award('mentor-'+selected,'Một cách đặt câu hỏi mới');render();(root.querySelector('[data-scientist-answer]')||root.querySelector('#scientist-reflection')).focus()});
 root.querySelector('#scientist-hint').addEventListener('click',()=>{root.querySelector('#scientist-feedback').textContent=scientists[selected].questions[step].hint});
 root.querySelector('#scientist-save').addEventListener('click',()=>{const s=scientists[selected],reflection=root.querySelector('#scientist-reflection').value.trim();const stored=api.saveNote(`Cuộc gặp với ${s.name}`,`${s.topic}\n${s.context}\n\nĐã khám phá ${Math.min(step+(correct?1:0),s.questions.length)}/${s.questions.length} gợi mở.\n${reflection?`Suy nghĩ của tôi:\n${reflection}`:'Câu hỏi tiếp theo của tôi: …'}\n\nNguồn: ${s.source[1]}\nTái hiện sư phạm bằng kịch bản, không phải trích dẫn lịch sử hoặc AI trực tiếp.`);if(stored)savedReflections[selected]=root.querySelector('#scientist-reflection').value});
 root.querySelector('#scientist-replay').addEventListener('click',()=>{step=0;correct=false;lastAnswer=-1;render()});render();return {setActive(){},hasDraft:()=>{capture();return Object.entries(sessions).some(([id,d])=>d.reflection.trim()&&d.reflection!==(savedReflections[id]||''))}};
}
export function createFieldStudio(root,api){
 let selected='osmosis';const drafts={},savedDrafts={};
 root.innerHTML=`<div class="studio-section-head"><div><span class="studio-kicker">05 / STEM TẠI BÀN</span><h2>Ra khỏi màn hình. Giữ lại bằng chứng.</h2><p>Từ một mô phỏng đến một quan sát thật. Chọn hoạt động nhỏ, ghi điều kiện, lưu số liệu của chính bạn.</p></div><span class="studio-label">SỔ TAY THỰC ĐỊA</span></div><div class="field-study-picker" role="group" aria-label="Chọn hoạt động thực địa">${Object.entries(fieldStudies).map(([id,s])=>`<button type="button" data-field-study="${id}"><span class="field-study-photo study-${id}" aria-hidden="true"></span><span><strong>${s.title}</strong><small>${s.subtitle}</small></span><b aria-hidden="true">↗</b></button>`).join('')}</div><div class="field-studio-layout"><div class="field-protocol"><span class="studio-kicker">CHUẨN BỊ & THỰC HIỆN</span><h3 id="field-title"></h3><div id="field-materials" class="field-materials"></div><ol id="field-steps"></ol><div class="field-variables"><div><span>YẾU TỐ ĐƯỢC XÉT</span><p id="field-variable"></p></div><div><span>CẦN GIỮ / GHI RÕ</span><p id="field-controls"></p></div></div></div><form id="field-form" class="field-record"><span class="studio-kicker">DỮ LIỆU THẬT / DO BẠN GHI</span><label for="field-hypothesis">Dự đoán trước khi quan sát</label><textarea id="field-hypothesis" name="hypothesis" rows="2" maxlength="800" placeholder="Nếu thay đổi… thì… vì…"></textarea><label for="field-conditions">Điều kiện & cách đo <span aria-hidden="true">*</span></label><textarea id="field-conditions" name="conditions" rows="2" maxlength="1000" required placeholder="Ngày giờ, vật liệu, lượng nước/muối, kích thước, thời gian…"></textarea><label for="field-data">Số liệu / điều nhìn thấy trực tiếp <span aria-hidden="true">*</span></label><textarea id="field-data" name="observations" rows="4" maxlength="1800" required placeholder="Mẫu A: ban đầu… sau…\nMẫu B: ban đầu… sau…\nNhớ ghi đơn vị và thời điểm."></textarea><label for="field-conclusion">Giải thích & điều chưa chắc chắn</label><textarea id="field-conclusion" name="conclusion" rows="3" maxlength="1000" placeholder="Kết quả có ủng hộ dự đoán? Còn yếu tố nào khác có thể ảnh hưởng?"></textarea><p id="field-question" class="field-guiding-question"></p><label class="field-confirmation"><input type="checkbox" id="field-observed" required> Tôi đã thực hiện quan sát và đang ghi lại dữ liệu của mình.</label><button type="submit" class="studio-button">Lưu phiếu quan sát vào sổ</button><p class="studio-fineprint">Phiếu được lưu trên thiết bị này. Không có cảm biến hay số liệu tự đo từ mô phỏng. Các hướng dẫn là hoạt động học tập gợi ý; tuân theo hướng dẫn của giáo viên.</p></form></div><div class="studio-insight"><span>MÔ HÌNH & THẾ GIỚI THẬT</span><p>Mô hình giúp đặt câu hỏi. Thực nghiệm tạo thêm bằng chứng và bộc lộ những điều mô hình đã giản lược. Một kết quả khác dự đoán vẫn là một điều đáng tìm hiểu.</p><a href="#/lab">Đối chiếu trong phòng thí nghiệm số →</a></div>`;
 const form=root.querySelector('#field-form');
 function capture(){drafts[selected]=Object.fromEntries(new FormData(form));drafts[selected].observed=root.querySelector('#field-observed').checked}
 function render(){const s=fieldStudies[selected];root.querySelector('#field-title').textContent=s.title;root.querySelector('#field-materials').innerHTML=s.materials.map(m=>`<span>${m}</span>`).join('');root.querySelector('#field-steps').innerHTML=s.steps.map((text,i)=>`<li><span>${i+1}</span><p>${text}</p></li>`).join('');root.querySelector('#field-variable').textContent=s.variable;root.querySelector('#field-controls').textContent=s.controls;root.querySelector('#field-question').textContent=s.prompt;for(const name of ['hypothesis','conditions','observations','conclusion'])form.elements[name].value=drafts[selected]?.[name]||'';root.querySelector('#field-observed').checked=drafts[selected]?.observed||false;root.querySelectorAll('[data-field-study]').forEach(b=>{const active=b.dataset.fieldStudy===selected;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))})}
 root.querySelectorAll('[data-field-study]').forEach(b=>b.addEventListener('click',()=>{capture();selected=b.dataset.fieldStudy;render()}));
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));if(!data.conditions.trim()||!data.observations.trim()){api.toast('Hãy ghi điều kiện và kết quả quan sát trước khi lưu.');return}const s=fieldStudies[selected];const saved=api.saveNote(`Thực địa: ${s.title}`,`Thời điểm lưu: ${new Date().toLocaleString('vi-VN')}\n\nDự đoán: ${data.hypothesis.trim()||'Chưa ghi'}\n\nĐiều kiện & cách đo:\n${data.conditions.trim()}\n\nSố liệu / quan sát:\n${data.observations.trim()}\n\nGiải thích & điều chưa chắc chắn:\n${data.conclusion.trim()||'Chưa ghi'}\n\nYếu tố xét: ${s.variable}\nCần ghi/giữ: ${s.controls}\nDữ liệu tự khai của người học, chưa được xác minh.`);capture();if(saved){savedDrafts[selected]=JSON.stringify(drafts[selected]);api.award('field-'+selected,'Đã giữ lại một phiếu quan sát')}});render();return {setActive(){},hasDraft:()=>{capture();return Object.entries(drafts).some(([id,d])=>['hypothesis','conditions','observations','conclusion'].some(k=>d[k]?.trim())&&JSON.stringify(d)!==savedDrafts[id])}};
}
